```python
def dedupe_contacts(rows):
    import re
    from datetime import datetime

    def normalize_email(value):
        value = value.strip()
        match = re.search(r"<([^<>]*)>", value)
        if match:
            value = match.group(1)

        value = value.strip().lower()
        if value.count("@") != 1:
            return ""

        local, domain = value.split("@")
        if domain in {"gmail.com", "googlemail.com"}:
            local = local.split("+", 1)[0].replace(".", "")
            domain = "gmail.com"

        if (
            not local
            or not domain
            or "." not in domain
            or domain.startswith(".")
            or domain.endswith(".")
        ):
            return ""

        return local + "@" + domain

    def normalize_phone(value):
        extension = re.search(r"(?:ext|x|#)", value, flags=re.IGNORECASE)
        if extension:
            value = value[:extension.start()]

        digits = re.sub(r"\D", "", value)
        if len(digits) == 11 and digits.startswith("1"):
            digits = digits[1:]

        if len(digits) != 10 or digits[0] in {"0", "1"}:
            return ""

        return digits

    def normalize_zip(value):
        value = value.strip()
        match = re.fullmatch(r"(\d{4,5})-\d{4}", value)
        if match:
            value = match.group(1)

        if re.fullmatch(r"\d{4}", value):
            value = "0" + value

        return value if re.fullmatch(r"\d{5}", value) else ""

    def normalize_name(value):
        value = value.strip()
        if value.isupper() or value.islower():
            return value.title()
        return value

    def parse_updated(value):
        for fmt in ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S"):
            try:
                return datetime.strptime(value.strip(), fmt)
            except ValueError:
                pass
        raise ValueError("Invalid updated value: {!r}".format(value))

    def is_opted_out(value):
        return value.strip().lower() in {"y", "yes", "true", "1"}

    normalized = []

    for index, row in enumerate(rows):
        email = normalize_email(row["email"])
        phone = normalize_phone(row["phone"])

        # Rows without either usable contact method cannot participate.
        if not email and not phone:
            continue

        tags = {
            tag.strip().lower()
            for tag in re.split(r"[;,]", row["tags"])
            if tag.strip()
        }

        source = row["source"].strip().lower()

        normalized.append({
            "index": index,
            "first_name": normalize_name(row["first_name"]),
            "last_name": normalize_name(row["last_name"]),
            "zip": normalize_zip(row["zip"]),
            "email": email,
            "phone": phone,
            "source": source,
            "tags": tags,
            "opted_out": is_opted_out(row["opted_out"]),
            "updated_dt": parse_updated(row["updated"]),
        })

    # Union-find over the retained rows.
    parent = list(range(len(normalized)))
    size = [1] * len(normalized)

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(a, b):
        a = find(a)
        b = find(b)
        if a == b:
            return
        if size[a] < size[b]:
            a, b = b, a
        parent[b] = a
        size[a] += size[b]

    email_owner = {}
    phone_last_owner = {}

    for i, row in enumerate(normalized):
        if row["email"]:
            previous = email_owner.get(row["email"])
            if previous is None:
                email_owner[row["email"]] = i
            else:
                union(i, previous)

        if row["phone"] and row["last_name"]:
            key = (row["phone"], row["last_name"].casefold())
            previous = phone_last_owner.get(key)
            if previous is None:
                phone_last_owner[key] = i
            else:
                union(i, previous)

    groups = {}
    for i, row in enumerate(normalized):
        groups.setdefault(find(i), []).append(row)

    def choose(group, field):
        candidates = [row for row in group if row[field]]
        if not candidates:
            return ""

        return max(
            candidates,
            key=lambda row: (
                row["source"] == "manual",
                row["updated_dt"],
                -row["index"],
            ),
        )[field]

    ordered_groups = sorted(
        groups.values(),
        key=lambda group: min(row["index"] for row in group),
    )

    result = []
    for group in ordered_groups:
        all_tags = set()
        for row in group:
            all_tags.update(row["tags"])

        latest_updated = max(row["updated_dt"] for row in group)

        result.append({
            "first_name": choose(group, "first_name"),
            "last_name": choose(group, "last_name"),
            "zip": choose(group, "zip"),
            "email": choose(group, "email"),
            "phone": choose(group, "phone"),
            "source": choose(group, "source"),
            "tags": ";".join(sorted(all_tags)),
            "opted_out": "Y" if any(row["opted_out"] for row in group) else "N",
            "updated": latest_updated.strftime("%Y-%m-%d"),
        })

    return result
